<section class="panel glow-panel assemblies-panel-063"><header class="panel-head"><div><span class="panel-kicker">SESTAVY</span><h2>Racky bez kilometrového seznamu</h2><p>Náhled obsahu, rozložení buněk a editace na jednom místě.</p></div><a class="btn" href="print.php?type=racks" target="_blank">QR všech sestav</a></header><div class="assembly-card-grid-063"><?php foreach($racks as $r):$items=$cagesByRack[(int)$r['id']]??[];$map=[];$overflow=[];foreach($items as $c){$rr=(int)($c['grid_row']??0);$cc=(int)($c['grid_col']??0);if($rr>0&&$cc>0)$map[$rr.'-'.$cc]=$c;else $overflow[]=$c;}?><article class="assembly-card-063"><header><div><?=ir_visual_icon('inventory')?><span><strong><?=ir_e((string)$r['nazev'])?></strong><small><?=ir_e((string)($r['umisteni']?:'Bez umístění'))?> · <?=$r['pocet_radku']?>×<?=$r['pocet_sloupcu']?></small></span></div><b><?=$r['cage_count']?> ubikací</b></header><div class="assembly-mini-grid-063" style="--cols:<?=max(1,(int)$r['pocet_sloupcu'])?>"><?php for($rr=1;$rr<=max(1,(int)$r['pocet_radku']);$rr++)for($cc=1;$cc<=max(1,(int)$r['pocet_sloupcu']);$cc++):$c=$map[$rr.'-'.$cc]??null;?><span class="<?=$c?'is-filled':'is-empty'?>" title="<?=$c?ir_e((string)$c['nazev']):'Volná pozice'?>"><?=$c?ir_visual_icon('habitat'):''?></span><?php endfor?></div><?php if($overflow):?><div class="assembly-overflow-063"><strong>Bez pozice:</strong> <?php foreach($overflow as $c):?><span><?=ir_e((string)$c['nazev'])?></span><?php endforeach?></div><?php endif?><footer><a class="btn small" href="habitats.php?view=assemblies&rack=<?=$r['id']?>">Upravit sestavu</a><a class="btn small" href="habitat-studio.php?rack=<?=$r['id']?>">Studio</a><a class="btn small" href="print.php?type=rack&id=<?=$r['id']?>" target="_blank">QR</a></footer></article><?php endforeach;if(!$racks):?><div class="empty-state">Zatím žádné sestavy.</div><?php endif?></div></section>
